from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Plan_destroy(EmssimCommand):
    def __init__(self, method="plan_destroy", timeout=60, rpc_connection_name='localRPC'):
        super(Plan_destroy, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Plan_destroy, self).on_new_data(**data)
        if 'msg' in data:
            if "Plan wasn't created yet":
                self._ret['plan_existed'] = 1
        elif ("status" in data):
            self._ret["status"] = data["status"]
